mapper.select:
select cot.id, cot.orgId, cot.oralTariffCategoryId, cot.oralTariffCategoryName, cot.oralTariffCategoryNumber, cot.oralTariffId, cot.`name`, cot.englishName, cot.`number`, cot.unit, cot.price, cot.inservice from ( select cot.id, cot.clinic_id as orgId, botbotc.oralTariffCategoryId, botbotc.oralTariffCategoryName, botbotc.oralTariffCategoryNumber, botbotc.oralTariffId, botbotc.`name`, botbotc.pinyin, botbotc.englishName, botbotc.`number`, botbotc.unit, cot.price, cot.inservice from clinic_oral_tariff cot left join ( select bot.id as oralTariffId, botc.id as oralTariffCategoryId, botc.`name` as oralTariffCategoryName, botc.number as oralTariffCategoryNumber, bot.item_number as number, bot.`name`, bot.pinyin, bot.english_name as englishName, bot.unit from base_oral_tariff bot left join base_oral_tariff_category botc on bot.oral_tariff_category_id = botc.id ) botbotc on cot.oral_tariff_id = botbotc.oralTariffId ) cot
and cot.id = #{queryForm.id}
and cot.orgId =#{queryForm.orgId}
and cot.oralTariffCategoryId = #{queryForm.oralTariffCategoryId}
and cot.oralTariffId = #{queryForm.oralTariffId}
and cot.name like concat('%',#{queryForm.keyWord},'%') or cot.pinyin like concat('%',#{queryForm.keyWord},'%') or cot.englishName like concat('%',#{queryForm.keyWord},'%')
and cot.inservice = #{queryForm.inservice}
